var current_focus_idx = 0;

function get_focus_span (focus_idx)
{
    const element_id = focus_ids[focus_idx];
    return document.getElementById(element_id);
}
function get_any_state_diagram (focus_idx)
{
    const element_id = focus_ids[focus_idx];
    return document.getElementById(element_id + "-state-diagram");
}
function unhighlight_current_focus_idx ()
{
    get_focus_span (current_focus_idx).classList.remove ('selected');
    state_diagram = get_any_state_diagram (current_focus_idx);
    if (state_diagram) {
        state_diagram.style.visibility = "hidden";
    }
}
function highlight_current_focus_idx ()
{
    const el = get_focus_span (current_focus_idx);
    el.classList.add ('selected');
    state_diagram = get_any_state_diagram (current_focus_idx);
    if (state_diagram) {
        state_diagram.style.visibility = "visible";
    }
    // Center the element on the screen
    const top_y = el.getBoundingClientRect ().top + window.pageYOffset;
    const middle = top_y - (window.innerHeight / 2);
    window.scrollTo (0, middle);
}
function select_prev_focus_idx ()
{
    unhighlight_current_focus_idx ();
    if (current_focus_idx > 0)
        current_focus_idx -= 1;
    else
        current_focus_idx = focus_ids.length - 1;
    highlight_current_focus_idx ();
}
function select_next_focus_idx ()
{
    unhighlight_current_focus_idx ();
    if (current_focus_idx < focus_ids.length - 1)
        current_focus_idx += 1;
    else
        current_focus_idx = 0;
    highlight_current_focus_idx ();
}
document.addEventListener('keydown', function (ev) {
    if (ev.key == 'j')
        select_next_focus_idx ();
    else if (ev.key == 'k')
        select_prev_focus_idx ();
});
highlight_current_focus_idx ();

